103: 			Severity:        toSeverity(issue.Severity),
104: 			Code:            issue.ID,
105: 			Source:          string(issue.Product),
106: 			Message:         issue.Message,
107: 			CodeDescription: lsp.CodeDescription{Href: lsp.Uri(s)},
108: 		})
109: 	}
110: 	return diagnostics
