120: func toHovers(issues []snyk.Issue) (hovers []hover.Hover[hover.Context]) {
121: 	for _, i := range issues {
122: 		message := ""
123: 		if len(i.FormattedMessage) > 0 {
124: 			message = i.FormattedMessage
125: 		} else {
126: 			message = i.Message
127: 		}
128: 
129: 		if len(i.References) > 0 {
130: 			message += "\n\nReferences:\n\n"
131: 			for _, reference := range i.References {
132: 				message += fmt.Sprintf("[%s](%s)\n\n", reference.Title, reference.Url)
133: 			}
134: 		}
135: 
136: 		hovers = append(hovers, hover.Hover[hover.Context]{
137: 			Id:      i.ID,
138: 			Range:   ToRange(i.Range),
139: 			Message: message,
140: 			Context: i,
141: 		})
142: 	}
143: 	return hovers
144: }

